insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-firing-takes-queue-after-routine-checkpoint-s721','decision','A firing takes the queue at a routine checkpoint''s merge','S721 conductor: the CPL Queue routine''s 10:12Z firing found S720''s checkpoint #3751 open, its handoff 721 complete to its last line and test running. It stayed read-only and took the queue when #3751 merged at 10:40Z (13d93cd1), as S681''s 10:12Z firing did. The rule for a hand-run session''s open PR stands as written.',array['conductor','routine','one-writer','handoffs'],'proposed','docs/session_722_handoff.md; #3751',null,null,'SkySkua (S721)','2026-11-24'),
('d-credential-watch-held-in-conductor-runs-s721','decision','The credential harvest held in conductor runs','S721 conductor: the routine''s step 10, the industry credential harvest, did not run; it has not run since 2026-11-13 (#3210). Conductor runs since 2026-11-17 hold to collection under Sam''s routine prompt of that day: "Conductor mode is back for collection only."',array['conductor','routine','credential-registry','scope'],'proposed','docs/session_722_handoff.md; docs/reference/scheduled_sessions.md step 10',null,null,'SkySkua (S721)','2026-11-24'),
('d-piles-land-as-one-pr-s721','decision','Four applied piles branches land as one PR','S721 conductor: the applied cheap-piles branches at Palo Verde, Porterville, Gavilan and Butte (42 records live) landed as one PR, #3769 (3d39f29b, 13:10Z), under the three-PR cap. Gavilan and Butte were pushed without PRs of their own; #3762 and #3767 closed with pointers to #3769. Orange Coast landed alone as #3765.',array['conductor','merge-order','program-requirements','piles'],'proposed','#3769; #3765',null,null,'SkySkua (S721)','2026-11-24'),
('d-palo-verde-41242-held-own-notes-s721','decision','Palo Verde 41242 held on its own notes','S721 conductor, on Palo Verde''s second reader (FIX THEN APPLY): 41242 holds unfiled, since none of its own notes says its 17.25 depends on FST 090''s 0.25-12 unit range, the standard 17998 set. 41227 holds too: its sum and stated total are not noted_figures_differ''s two figures. Plan s721a went to 15 rows.',array['program-requirements','palo-verde','named-gaps','held'],'proposed','#3769 (plan s721a)',null,null,'SkySkua (S721)','2026-11-24'),
('d-miracosta-force-07863-only-s721','decision','MiraCosta''s forced re-read on 07863 alone','S721 conductor: MiraCosta''s forced re-read ran on 07863 alone (45392607854, $0.08 against $0.11; load 45397967009, passing). 36144 and 36171 are text_window_cut named gaps, their section printing past the 16,000 characters the capture sends; 15183 and 22006 are named gaps, since the Teacher list does not print CDEV 212.',array['program-requirements','miracosta','lever','paid-reads'],'proposed','#3763',null,null,'SkySkua (S721)','2026-11-24'),
('d-land-merged-without-main-update-s721','decision','#3769 merged without an update from main','S721 conductor: #3769, the land PR, merged as 3d39f29b without the one update from main before its merge: main had moved only by S722''s 23a03d6c (#3768, a Courses count read from its code''s own course file), which touches none of its files.',array['conductor','merge','program-requirements'],'proposed','#3769; #3768',null,null,'SkySkua (S721)','2026-11-24'),
('d-orange-coast-lever-waits-s721','decision','Orange Coast''s lever programs wait for lane 2','S721 conductor: lane 2 held Orange Coast for its piles plan s721b (#3765), so the 8 Orange Coast programs on the census''s reader_page_assignment lever waited, under Sam''s routine prompt of 2026-11-17: "Two lanes, never on the same college". They go to the next run''s lever.',array['conductor','lanes','orange-coast','lever'],'proposed','docs/session_722_handoff.md',null,null,'SkySkua (S721)','2026-11-24'),
('d-no-new-workers-after-12z-s721','decision','No new workers once spend passed about $110','S721 conductor: S720 spent about $255 earlier on the UTC day, so the run aimed at about $150 against the $750 daily cap. Once its estimated spend passed about $110 (about $112 at 12:22Z, from the transcripts'' token counts at kb/_spend_meter.py''s rates), it started no new worker and landed what was in flight.',array['conductor','spend','routine'],'proposed','docs/session_722_handoff.md',null,null,'SkySkua (S721)','2026-11-24'),
('p-test-reads-own-apply-receipt-s721','pitfall','A plan''s test must not read its own receipt','S721: #3764''s recall took its answers from plan s721p''s own receipt and could never fail (a round 1 blocker). Porterville''s test passed before its apply and failed after it: its live-run check read the receipt the apply posts. The recall now runs live against hand answers (55 of 55), and the check reads the receipts as they stood before the plan''s own apply.',array['program-requirements','testing','receipts','guarded-update'],'proposed','#3764 (dc90eb2a); #3769; docs/kb-notes/methodology-a-test-must-not-take-its-rule-as-the-truth.md',null,null,'SkySkua (S721)','2026-11-24'),
('p-test-asserts-other-pr-absent-s721','pitfall','A test must not assert another PR''s change absent','S721: Butte''s piles test held 01312 by asserting that #3762''s new kind, degree_electives_not_printed, was absent; that turned false once the Palo Verde and Butte branches landed together in #3769. It now asserts 01312 is not among Butte''s reviewed records. A test holds before and after any PR it does not depend on.',array['program-requirements','testing','merge-order'],'proposed','#3769',null,null,'SkySkua (S721)','2026-11-24'),
('p-plan-file-push-starts-page-read-s721','pitfall','A push touching kb/college_reads starts a page read','S721: a push that touches kb/college_reads/*.json starts the page-read workflow on that branch, so a read''s plan commit goes last on its push (Saddleback''s A-Z navigation read went that way), and a third queued run cancels the pending one, as S714''s one-pending-run rule warns (p-one-pending-run-per-branch-s714).',array['program-requirements','workflows','page-read','lever'],'proposed','#3763 (2af19860)',null,null,'SkySkua (S721)','2026-11-24'),
('p-pin-test-sets-production-mark-s721','pitfall','A pin test marks its members as the capture does','S721: #3763''s pin test left its programs unmarked, so rule B never ran in it. In production every lever member is marked (RC.MARK), and rule B refused Antelope Valley''s 8 pins, whose degree pages print their GE map. Round 1 caught it before any paid read; the test marks its programs, and RC.PIN_HEADING passes a pin whose heading names its program.',array['program-requirements','testing','reader','lever'],'proposed','#3763 (55356e0e)',null,null,'SkySkua (S721)','2026-11-24'),
('p-named-gap-asserts-only-the-page-s721','pitfall','A named gap''s test states only what its page prints','S721: #3763''s second reader found MiraCosta''s checks placing CDEV 212 in the Associate Teacher list, where the page prints it in Early Intervention. A named gap''s test and fixture state only what its own page prints, in the capture''s own form (the award line as the capture holds it).',array['program-requirements','named-gaps','testing','miracosta'],'proposed','#3763 (55356e0e)',null,null,'SkySkua (S721)','2026-11-24'),
('p-gap-filing-leaves-census-lever-s721','pitfall','A record a cheaper lever passes is never gap-filed','S721: Butte''s second reader held, as a blocker, nine degree_within_map_range records that pass today''s scorer once the map''s elective line reads as electives that fill the degree. A named gap takes a record off the census lever that would pass it, so such a record is held with its reason and stays on reconcile_steps.',array['program-requirements','named-gaps','census','butte'],'proposed','#3769 (plan s721e)',null,null,'SkySkua (S721)','2026-11-24'),
('p-force-reread-needs-text-window-s721','pitfall','A forced re-read needs a text window that reaches the section','S721: MiraCosta 36144 and 36171''s section prints past the 16,000 characters the capture sends, so a forced re-read would send the same cut text and pay for nothing. Both were filed as text_window_cut named gaps, and only 07863 was forced (d-miracosta-force-07863-only-s721).',array['program-requirements','reader','paid-reads','miracosta'],'proposed','#3763 (55356e0e)',null,null,'SkySkua (S721)','2026-11-24'),
('f-cert-heading-accepts-plural-department-s721','fact','A certificate''s heading check accepts a plural department heading','S721: #3763''s second reader, round 2 (DISPATCH), left one minor open: a certificate''s heading check in the reader''s pin rules accepts a plural department heading. It goes to the night''s one follow-up PR, after the waves.',array['program-requirements','reader','follow-up'],'proposed','#3763',null,null,'SkySkua (S721)','2026-11-24'),
('f-degree-within-map-range-keep-unchecked-s721','fact','A kept degree_within_map_range gap is not rechecked','S721: a reconcile keeps a filed degree_within_map_range named gap (#3756''s keep_named_gaps) without checking within_map, the test its filing requires (the sample map''s range starts at the printed 60 and the degree''s units fall strictly inside it). A follow-up minor: the keep should check it.',array['program-requirements','named-gaps','reconcile','follow-up'],'proposed','#3769 (kb/_program_named_gaps.py)',null,null,'SkySkua (S721)','2026-11-24'),
('f-butte-nine-pass-on-elective-line-s721','fact','Butte''s nine pass on the map''s elective line','S721: Butte 01362, 07269, 11136, 31042, 31941, 32469, 33199, 40923 and 43453 each count the sample map''s line "Only necessary if the 60 units needed to graduate have not been completed" at its printed figure. Read as electives that fill the degree, each passes today''s scorer: a Butte reconcile step''s work.',array['program-requirements','butte','reconcile'],'proposed','#3769 (receipt s721e)',null,null,'SkySkua (S721)','2026-11-24'),
('f-orange-coast-wording-rules-s721','fact','Orange Coast''s two wording rules for a later run','S721: Orange Coast''s plan s721b (#3765) collected 3 of the census''s 20 with named gaps and held 17. Two of the holds are free wording rules for a later run: 08670''s degree_total_minimum and 32737''s substitution list.',array['program-requirements','orange-coast','wording-rules'],'proposed','#3765',null,null,'SkySkua (S721)','2026-11-24'),
('f-modesto-s720j-holds-pass-pooled-s721','fact','Five of Modesto''s s720j holds pass pooled','S721: under #3764''s pooled reading, five of Modesto Junior''s 13 s720j holds pass today''s scorer: 08104, 08111, 33944, 37300 and 38067. Plan s721p leaves the 13 as they are; the five are the pooled reading''s next rows once #3764 is applied. S720''s plan s720j is superseded by s721p and never merges.',array['program-requirements','modesto-junior','pooled','held'],'proposed','#3764; claude/s720-piles-modesto',null,null,'SkySkua (S721)','2026-11-24'),
('f-pooled-flips-elsewhere-s721','fact','The pooled reading flips records outside its plan','S721: #3764''s statewide self-recall moves 28 records from fail to pass and none from pass to fail. Plan s721p takes 14 at its colleges; Rio Hondo 3, Cuyamaca 2 and Golden West 1 flip outside them and wait for the next run, with Modesto''s 5 s720j holds and El Camino 02513, 02515 and 02517 (an electives fill needs the page text).',array['program-requirements','scorer','pooled','follow-up'],'proposed','#3764',null,null,'SkySkua (S721)','2026-11-24'),
('m-collection-s721','milestone','S721''s collection: 49 records live at the checkpoint','S721 (2026-11-24), at the checkpoint''s writing: 49 program records collected and live for $0.33 of paid reads. 45 cheap-piles records at five colleges, 44 with named gaps and 1 passing (Orange Coast 3, #3765; Palo Verde 15, Porterville 15, Gavilan 7, Butte 5, #3769); 4 lever loads (Redwoods 3, MiraCosta 1; #3763), 14 named gaps filed. Display build 6de40ebdf2fd (#3761).',array['program-requirements','collection','milestone'],'proposed','#3761; #3765; #3769; #3763',null,null,'SkySkua (S721)','2026-11-24')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
